128	export function TenantPortal() {
129	  const [data, setData] = useState<Data | null>(null);
130	  const [failed, setFailed] = useState(false);
131	  // "now" exists only on the client after mount, so statuses never differ between server and browser (R52).
132	  const [now, setNow] = useState<Date | null>(null);
133	  const [reloadKey, setReloadKey] = useState(0);
134	
135	  useEffect(() => {
136	    let cancelled = false;
137	    loadData()
138	      .then((d) => {
139	        if (cancelled) return;
140	        setData(d);
141	        setNow(new Date());
142	        setFailed(false);
143	      })
144	      .catch(() => {
145	        if (cancelled) return;
146	        setFailed(true);
147	        toast.error("Could not load your tenancy");
148	      });
149	    return () => {
150	      cancelled = true;
151	    };
152	  }, [reloadKey]);
153	
154	  function reload() {
155	    setData(null);
156	    setFailed(false);
157	    setReloadKey((k) => k + 1);
158	  }
159	
160	  if (failed) {
161	    return (
162	      <Card className="max-w-md">
163	        <CardHeader>
164	          <CardTitle>Something went wrong</CardTitle>
165	          <CardDescription>Your tenancy could not be loaded.</CardDescription>
166	        </CardHeader>
167	        <CardContent>
168	          <Button onClick={reload}>Try again</Button>
169	        </CardContent>
170	      </Card>
171	    );
172	  }
173	
174	  if (!data || !now) return <PortalSkeleton />;
175	
176	  if (data.tenants.length === 0) {
177	    return (
178	      <Card className="max-w-md">
179	        <CardHeader>
180	          <CardTitle>No tenancy found</CardTitle>
181	          <CardDescription>This account is not linked to a tenant profile.</CardDescription>
182	        </CardHeader>
183	      </Card>
184	    );
185	  }
186	
187	  return (
188	    <div className="flex flex-col gap-6">
189	      <div className="flex flex-wrap items-center justify-between gap-3">
190	        <h1 className="text-2xl font-semibold tracking-tight">My tenancy</h1>
191	        <Button variant="outline" onClick={reload}>
192	          Refresh
193	        </Button>
194	      </div>
195	
196	      {data.tenants.map((t) => (
197	        <Card key={t.id}>
198	          <CardHeader>
199	            <CardTitle>{t.full_name}</CardTitle>
200	            <CardDescription>{t.email}</CardDescription>
201	          </CardHeader>
202	          <CardContent>
203	            <PhoneForm
204	              tenantId={t.id}
205	              phone={t.phone}
206	              onSaved={(phone) =>
207	                setData((d) => (d ? { ...d, tenants: d.tenants.map((x) => (x.id === t.id ? { ...x, phone } : x)) } : d))
208	              }
209	            />
210	          </CardContent>
211	        </Card>
212	      ))}
213	
214	      {data.leases.length === 0 ? (
215	        <Card className="max-w-md">
216	          <CardHeader>
217	            <CardTitle>No leases</CardTitle>
218	            <CardDescription>You do not have a lease yet.</CardDescription>
219	          </CardHeader>
220	        </Card>
221	      ) : (
222	        data.leases.map((lease) => (
223	          <LeaseSection
224	            key={lease.id}
225	            lease={lease}
226	            invoices={data.invoices.filter((i) => i.leaseId === lease.id)}
227	            payments={data.payments.filter((p) => p.leaseId === lease.id)}
228	            paidByInvoice={data.paidByInvoice}
229	            now={now}
230	          />
231	        ))
232	      )}
233	    </div>
234	  );
235	}
236	
237	function PortalSkeleton() {
238	  return (
239	    <div className="flex flex-col gap-6" aria-busy="true" aria-label="Loading your tenancy">
240	      <Skeleton className="h-8 w-48" />
241	      <Skeleton className="h-32 w-full" />
242	      <Skeleton className="h-64 w-full" />
243	      <Skeleton className="h-48 w-full" />
244	    </div>
245	  );
246	}
